/* @lc app=leetcode id=935 lang=kotlin */ class Solution { fun knightDialer(n: Int): Int = (1 until n).fold(LongArray(10) { 1 }) { c, _ -> LongArray(10) { i -> listOf(listOf(4, 6), listOf(6, 8), listOf(7, 9), listOf(4, 8), listOf(3, 9, 0), listOf<Int>(), listOf(1, 7, 0), listOf(2, 6), listOf(1, 3), listOf(2, 4))[i].sumOf { c[it] } % 1_000_000_007 } }.sum().mod(1_000_000_007L).toInt() }